// Generated by vibelang from src/features/views/conversation.ts; the migrate flow writes it again with each batch.
import { FlowRuntime } from "@smthrs/flow";
import { Effect } from "effect";
import { requesterOf } from "../../flows/requests";
// Where a step's view goes (decision 0013 §1), for every flow that adds views (`app/web/open`, `app/docs/search`): an
// agent's call is a child of its answer's run, so it goes to that answer's conversation, which ChatApi looks up, however
// the person's tab moved since; a person's goes to the conversation pinned when they dispatched it. The execution id
// says which, so a resumed run decides the same.
const isUuid = (value) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
/** The `answerId` or `conversationId` a `POST /api/views` write names for the running execution. */
export const viewConversation = (conversationId) => Effect.map(FlowRuntime.FlowInstance, ({ executionId }) => {
    const requester = requesterOf(executionId);
    if (requester !== executionId && isUuid(requester))
        return { answerId: requester.toLowerCase() };
    return conversationId === undefined ? {} : { conversationId };
});
/** Whether the running execution is the agent's call: a child of its answer's run. */
export const isAgentCall = Effect.map(FlowRuntime.FlowInstance, ({ executionId }) => requesterOf(executionId) !== executionId);
